        rts                         ; (the high byte needs no patch: both tables in one page)
        .assert >RINGHI = >RINGHI_B, error, "select_backbuf patches only RINGHIOP's low byte: RINGHI and RINGHI_B must share a page"
@thl:   .byte <RINGHI, <RINGHI_B

original:
@jump:  ble16i vy, -384, @j20
        bge16i vy, 384, @j24
        lda #22
        bne @sprf
@j20:   lda #20
        bne @sprf                   ; always: Z = 0 from the load
@j24:   lda #24

proposal:
        lda #1                      ; snake visible
        bne @vis                    ; always: A = 1
@nowarm:
        lda #0
@vis:   sta q6

; dead (the >>2 below shifts the low byte alone,
; no clc: s and 4s are even, so a carry in only sets
